import React from 'react';

const Navbar = ({ username, balance, onLogout, setActiveTab, activeTab }) => {
    const tabs = [
        { id: 'explore', label: 'Explore' },
        { id: 'holdings', label: 'Holdings' },
        { id: 'positions', label: 'Positions' },
        { id: 'orders', label: 'Orders' },
        { id: 'watchlist', label: 'Watchlist' },
        { id: 'recharge', label: 'Recharge' },
    ];

    return (
        <nav style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: '12px 30px',
            background: '#141b2b',
            borderBottom: '1px solid #2a3a5c',
            position: 'sticky',
            top: 0,
            zIndex: 100
        }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
                <h2 style={{ color: '#4CAF50', margin: 0, fontSize: '20px', cursor: 'pointer' }} 
                    onClick={() => setActiveTab('explore')}>
                    📈 DemoTrader
                </h2>
                <span style={{
                    fontSize: '10px',
                    background: '#1a2332',
                    padding: '2px 8px',
                    borderRadius: '10px',
                    color: '#8a9bb5'
                }}>DEMO</span>
            </div>

            {/* Navigation Tabs */}
            <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap' }}>
                {tabs.map((tab) => (
                    <button
                        key={tab.id}
                        onClick={() => setActiveTab(tab.id)}
                        style={{
                            padding: '6px 14px',
                            background: activeTab === tab.id ? '#2a3a5c' : 'transparent',
                            color: activeTab === tab.id ? '#e0e6ed' : '#8a9bb5',
                            border: activeTab === tab.id ? '1px solid #4CAF50' : '1px solid transparent',
                            borderRadius: '6px',
                            cursor: 'pointer',
                            fontSize: '13px',
                            transition: 'all 0.2s'
                        }}
                    >
                        {tab.label}
                    </button>
                ))}
            </div>
            
            <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                    <span style={{ color: '#8a9bb5' }}>👤</span>
                    <span style={{ color: '#e0e6ed', fontSize: '14px' }}>{username}</span>
                </div>
                <div style={{
                    background: '#1a2332',
                    padding: '6px 14px',
                    borderRadius: '6px',
                    border: '1px solid #2a3a5c',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px'
                }}>
                    <span>💰</span>
                    <span style={{ fontWeight: 'bold', color: '#4CAF50' }}>
                        ₹{balance.toFixed(2)}
                    </span>
                </div>
                <button
                    onClick={onLogout}
                    style={{
                        padding: '6px 16px',
                        background: '#dc3545',
                        color: 'white',
                        border: 'none',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        fontSize: '13px'
                    }}
                >
                    Logout
                </button>
            </div>
        </nav>
    );
};

export default Navbar;
